import Foundation

struct SimilarExpression: Codable, Equatable, Sendable {
    let english: String
    let chinese: String
}

struct SentenceAnalysis: Codable, Equatable, Sendable {
    /// Verbatim subtitle span attached by the app, not generated by the model.
    /// Optional for decoding notes made by earlier app versions.
    let analyzedEnglish: String?
    let translationZh: String
    let keyExpression: String
    let expressionMeaningZh: String
    let usageNoteZh: String
    let exampleEnglish: String
    let exampleChinese: String
    let similarExpressions: [SimilarExpression]

    init(
        translationZh: String,
        keyExpression: String,
        expressionMeaningZh: String,
        usageNoteZh: String,
        exampleEnglish: String,
        exampleChinese: String,
        similarExpressions: [SimilarExpression] = [],
        analyzedEnglish: String? = nil
    ) {
        self.analyzedEnglish = analyzedEnglish
        self.translationZh = translationZh
        self.keyExpression = keyExpression
        self.expressionMeaningZh = expressionMeaningZh
        self.usageNoteZh = usageNoteZh
        self.exampleEnglish = exampleEnglish
        self.exampleChinese = exampleChinese
        self.similarExpressions = similarExpressions
    }

    private enum CodingKeys: String, CodingKey {
        case analyzedEnglish
        case translationZh
        case keyExpression
        case expressionMeaningZh
        case usageNoteZh
        case exampleEnglish
        case exampleChinese
        case similarExpressions
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        analyzedEnglish = try container.decodeIfPresent(String.self, forKey: .analyzedEnglish)
        translationZh = try container.decode(String.self, forKey: .translationZh)
        keyExpression = try container.decode(String.self, forKey: .keyExpression)
        expressionMeaningZh = try container.decode(
            String.self,
            forKey: .expressionMeaningZh
        )
        usageNoteZh = try container.decode(String.self, forKey: .usageNoteZh)
        exampleEnglish = try container.decode(String.self, forKey: .exampleEnglish)
        exampleChinese = try container.decode(String.self, forKey: .exampleChinese)
        similarExpressions = try container.decodeIfPresent(
            [SimilarExpression].self,
            forKey: .similarExpressions
        ) ?? []
    }

    /// The wire payload has no source field. In plain-JSON fallback a model
    /// may emit extra keys anyway; none can replace the app's source.
    struct Generated: Decodable {
        let translationZh: String
        let keyExpression: String
        let expressionMeaningZh: String
        let usageNoteZh: String
        let exampleEnglish: String
        let exampleChinese: String
        let similarExpressions: [SimilarExpression]

        func anchored(to source: String) -> SentenceAnalysis {
            SentenceAnalysis(translationZh: translationZh, keyExpression: keyExpression,
                expressionMeaningZh: expressionMeaningZh, usageNoteZh: usageNoteZh,
                exampleEnglish: exampleEnglish, exampleChinese: exampleChinese,
                similarExpressions: similarExpressions, analyzedEnglish: source)
        }
    }
}

struct AIAnalysisRequest: Equatable, Sendable {
    let english: String
    let chinese: String
    let previousEnglish: String?
    let nextEnglish: String?
    var sourceContext: SubtitleSentenceContext? = nil

    /// With a real track the app already selected a contiguous span. Without
    /// timestamps use the same conservative boundaries for adjacent text.
    var contextualEnglish: String {
        if let sourceContext { return sourceContext.english }
        var parts: [String] = []
        if let previousEnglish, Self.continues(previousEnglish, into: english) { parts.append(previousEnglish) }
        parts.append(english)
        if let nextEnglish, Self.continues(english, into: nextEnglish) { parts.append(nextEnglish) }
        return parts.joined(separator: " ")
    }

    private static func continues(_ left: String, into right: String) -> Bool {
        SubtitleSentenceContext.groups(in: [
            SubtitleCue(startMilliseconds: 0, endMilliseconds: 1_000, text: left),
            SubtitleCue(startMilliseconds: 1_000, endMilliseconds: 2_000, text: right)
        ]).count == 1
    }
}

enum AnalysisState: Equatable {
    case idle
    case loading
    case loaded(SentenceAnalysis)
    case failed(String)
}
